/**
 * @param {Object|Array} obj
 * @return {boolean}
 */
var isEmpty = function(obj) {
    // for...in visits keys (array indices too); the first one proves non-empty,
    // so we bail out immediately -> O(1) (Object.keys(obj).length would be O(n))
    for (const key in obj) {
        return false;
    }
    return true;
};
